// 100x100 figure art, traced straight from the concept images rather than
// redrawn: each source was cropped to its subject, keyed off its flat backdrop
// and fitted into the square. Stored as base64 PNGs so the game keeps its "no
// external files" property — the service worker has nothing extra to cache.
// figures.js decodes these on load and prefers them over its painters.
const FIGURE_ART = {
  hero_knight: '',
  hero_mage: '',
  hero_warden: '',
  npc_alchemist: '',
  hero_necromancer: '',
};

// hero_rogue: plague-doctor thief, cut from the user's own reference sheet (overrides the painter)
FIGURE_ART.hero_rogue = '';

// hero_mage: Hollow Witch, cut from the user's own reference sheet (overrides the old traced mage)
FIGURE_ART.hero_mage = '';
